--
-- Table structure for table `scholarship_journal_items`
--

CREATE TABLE `scholarship_journal_items` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `journal_id` bigint(20) UNSIGNED NOT NULL,
  `gpa_current_semester` decimal(3,2) DEFAULT NULL,
  `cumulative_gpa` decimal(3,2) DEFAULT NULL,
  `academic_summary` text DEFAULT NULL,
  `class_attendance_percentage` tinyint(3) UNSIGNED DEFAULT NULL,
  `organization_activities` text DEFAULT NULL,
  `training_seminars` text DEFAULT NULL,
  `achievements` text DEFAULT NULL,
  `community_service_details` text DEFAULT NULL,
  `service_hours` smallint(5) UNSIGNED DEFAULT NULL,
  `personal_reflection` text DEFAULT NULL,
  `next_month_goals` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

